Bash(iverilog -g2012 -s startup_tb -o /tmp/spi_lcd_startup_check.vvp ctrl.v /dev/stdin <<'EOF'
`timescale 1ns/1ps
module startup_tb;
reg clk=0;
always #41.666667 clk=~clk;
wire lcd_rst,init_tx;
real released;
ctrl #(.RECOVERY_TICKS(2880000)) dut(.clk(clk),.restart(1'b0),.last_addr(1'b0),.st_delay(1'b0),.src_valid(1'b1),.done_tx(1'b0),.done_delay(1'b0),.rst(lcd_rst),.init_tx(init_tx));
always @(posedge lcd_rst) released=$realtime;
initial begin
#1;
if(dut.state!==0 || dut.rst_cnt!==0) $fatal(1,"Power-on initialization failed");
@(posedge init_tx);
if($realtime-released < 240000000.0) $fatal(1,"Recovery too short");
$display("PASS: startup without button; recovery=%0.6f ms",($realtime-released)/1000000.0);
@(posedge clk);
dut.state=4'd15;
dut.rst_cnt=32'd123;
@(negedge clk);
#1;
if(dut.state!==0 || dut.rst_cnt!==0 || lcd_rst!==0) $fatal(1,"Default recovery failed");
$display("PASS: default initializes state and reset counter");
$finish;
end
initial #300000000 $fatal(1,"Timeout");
endmodule
EOF
vvp /tmp/spi_lcd_startup_check.vvp)

